   title:const Text('Choose a new time'),content:SizedBox(width:420,child:Wrap(spacing:10,runSpacing:8,
   children:(availability!['slots']as List).where((s)=>(s['spotsAvailable']as num? ??1)>0&&s['startTime']!=row['data']['startTime'])
    .map((s)=>OutlinedButton(onPressed:()=>Navigator.pop(ctx,s['startTime']),child:Text(time(s['startTime'],s['businessTimezone'])))).toList())),
   actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Keep current time'))]));
  if(chosen!=null)await action(()async{await client.move(row['sk'],chosen);lastSaved=await client.read(row['sk']);bookings=await client.mine();notice='Time changed. Reference ${lastSaved!['data']['name']} is unchanged.';});
 }
